// Normalize the n8n error payload into a structured log row.
const e = $json;
const run = e.execution ?? {};
const wf = e.workflow ?? {};
const lastNodeExecuted = run.lastNodeExecuted ?? 'unknown';
const errMessage = run.error?.message ?? 'unknown error';

// request_id / company_id travel in the failed execution's input data when available.
const firstItem = run.error?.context?.itemIndex !== undefined ? run.error.context : {};

return [{ json: {
  company_id: firstItem.company_id ?? null,
  request_id: firstItem.request_id ?? run.id ?? null,
  workflow: wf.name ?? 'unknown',
  level: 'error',
  event: 'workflow_failed',
  detail: {
    execution_id: run.id,
    execution_url: run.url,
    node: lastNodeExecuted,
    message: errMessage,
    stack: run.error?.stack ?? null,
  },
} }];
